#include "sgre/scene/affine_trigonometry.hpp"

#include <array>
#include <bit>
#include <cmath>
#include <cstdint>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <string>
#include <string_view>

static void Require(bool condition, std::string_view message) {
	if (!condition) {
		throw std::runtime_error(std::string(message));
	}
}

static void CheckNativeBoundaryWords() {
	// Independently retained unchanged native SSE2 sine/cosine words, not generated by this implementation.
	const std::array<std::array<std::uint32_t, 3>, 20> vectors{{
	    {0x00000000, 0x00000000, 0x3f800000},
	    {0x80000000, 0x80000000, 0x3f800000},
	    {0x00000001, 0x00000001, 0x3f800000},
	    {0x80000001, 0x80000001, 0x3f800000},
	    {0x38ffffff, 0x38ffffff, 0x3f800000},
	    {0x39000000, 0x39000000, 0x3f800000},
	    {0x39000001, 0x39000001, 0x3f800000},
	    {0x3bffffff, 0x3bffff54, 0x3f7ffe00},
	    {0x3c000000, 0x3bffff55, 0x3f7ffe00},
	    {0x3c000001, 0x3bffff57, 0x3f7ffe00},
	    {0x3f490fda, 0x3f3504f3, 0x3f3504f4},
	    {0x3f490fdb, 0x3f3504f3, 0x3f3504f3},
	    {0x3f490fdc, 0x3f3504f4, 0x3f3504f2},
	    {0x3fc90fda, 0x3f800000, 0x33a22169},
	    {0x3fc90fdb, 0x3f800000, 0xb33bbd2e},
	    {0x3fc90fdc, 0x3f800000, 0xb42eef4c},
	    {0x40490fdb, 0xb3bbbd2e, 0xbf800000},
	    {0x40c90fdb, 0x343bbd2e, 0x3f800000},
	    {0x48f423ff, 0x3e557ebd, 0xbf7a5fcc},
	    {0xc8f423ff, 0xbe557ebd, 0xbf7a5fcc},
	}};
	for (const auto& vector : vectors) {
		const auto result = sgre::scene::PrepareAffineTrigonometry(std::bit_cast<float>(vector[0]));
		Require(std::bit_cast<std::uint32_t>(result.Sine) == vector[1] && std::bit_cast<std::uint32_t>(result.Cosine) == vector[2], "native trigonometric branch/cancellation vector");
	}
}

static void CheckIndependentSymmetry() {
	for (const auto input : {0.0f, 0.02f, 0.75f, 3.0f, 30.0f, 499999.0f}) {
		const auto positive = sgre::scene::PrepareAffineTrigonometry(input);
		const auto negative = sgre::scene::PrepareAffineTrigonometry(-input);
		Require((std::bit_cast<std::uint32_t>(positive.Sine) ^ 0x80000000u) == std::bit_cast<std::uint32_t>(negative.Sine) && positive.Cosine == negative.Cosine, "float sine/cosine preserve odd/even symmetry and signed zero");
		const auto length = static_cast<double>(positive.Sine) * positive.Sine + static_cast<double>(positive.Cosine) * positive.Cosine;
		Require(std::abs(length - 1) < 2e-7, "independent unit-circle invariant");
	}
}

static void CheckUnsupportedDomain() {
	for (const auto input : {500000.0f, -500000.0f, std::numeric_limits<float>::infinity(), std::numeric_limits<float>::quiet_NaN()}) {
		bool rejected = false;
		try {
			static_cast<void>(sgre::scene::PrepareAffineTrigonometry(input));
		} catch (const std::runtime_error& error) {
			rejected = std::string_view(error.what()).find("parity is not recovered") != std::string_view::npos;
		}
		Require(rejected, "large/nonfinite reduction must remain explicitly unrecovered");
	}
}

int main() {
	try {
		CheckNativeBoundaryWords();
		CheckIndependentSymmetry();
		CheckUnsupportedDomain();
		std::cout << "Three affine trigonometry fixture groups passed\n";
	} catch (const std::exception& error) {
		std::cerr << error.what() << '\n';

		return 1;
	}
}
